problems AS (
 SELECT 'guard_body_changed' AS problem,p.proname::text AS subject,k.source AS detail
 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace JOIN known_functions k ON k.name=p.proname
 WHERE n.nspname='public' AND (encode(public.digest(p.prosrc,'sha256'),'hex') NOT IN(k.old_digest,k.new_digest) OR p.prorettype<>'trigger'::regtype OR p.pronargs<>0)
 UNION ALL
 SELECT 'guard_attributes_changed',p.proname::text,'Expected published invoker, volatile PL/pgSQL trigger attributes and search path'
 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace JOIN known_attributes k ON k.name=p.proname
 JOIN pg_language l ON l.oid=p.prolang
 WHERE n.nspname='public' AND (p.prosecdef OR p.provolatile<>'v' OR p.proisstrict OR p.proleakproof OR p.proparallel<>'u' OR l.lanname<>'plpgsql'
   OR coalesce((SELECT jsonb_agg(regexp_replace(value,'\s','','g') ORDER BY value) FROM unnest(p.proconfig) value),'[]'::jsonb)<>k.config)
 UNION ALL
 SELECT 'production_function_missing',k.name,'Apply the selected production and payroll migrations after the native retirement authority prerequisite'
 FROM production_functions k WHERE (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname=k.name)<>1
 UNION ALL
 SELECT 'production_table_changed',k.table_name,'Expected the published tenant-owned extension table with a required UUID org_id'
 FROM production_tables k WHERE NOT EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
   JOIN pg_attribute a ON a.attrelid=c.oid WHERE n.nspname='public' AND c.relname=k.table_name AND c.relkind='r'
   AND a.attname='org_id' AND a.atttypid='uuid'::regtype AND a.attnotnull AND NOT a.attisdropped)
 UNION ALL
 SELECT 'production_trigger_changed',k.table_name||'.'||k.trigger_name,'Expected the published trigger function, events, timing, row scope and deferral'
 FROM production_triggers k WHERE NOT EXISTS(SELECT 1 FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid
   JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_proc p ON p.oid=t.tgfoid JOIN pg_namespace pn ON pn.oid=p.pronamespace
   WHERE n.nspname='public' AND c.relname=k.table_name AND t.tgname=k.trigger_name AND pn.nspname='public' AND p.proname=k.function_name
   AND t.tgtype::integer=k.trigger_type AND t.tgdeferrable=k.is_deferrable AND t.tginitdeferred=k.initially_deferred
   AND t.tgenabled IN ('O','A') AND NOT t.tgisinternal AND t.tgnargs=0 AND t.tgqual IS NULL AND t.tgattr::text='')
 UNION ALL
 SELECT 'unknown_delete_trigger',c.relname||'.'||t.tgname,p.proname::text
 FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_proc p ON p.oid=t.tgfoid JOIN pg_namespace pn ON pn.oid=p.pronamespace
 WHERE n.nspname='public' AND NOT t.tgisinternal AND (t.tgtype::integer & 8)<>0
 AND NOT (t.tgname IN ('tenant_retirement_fence','tenant_retirement_org_fence') AND pn.nspname='tenant_retirement' AND p.proname='openbooks_tenant_retirement_fence')
 AND NOT EXISTS(SELECT 1 FROM known_triggers k WHERE k.table_name=c.relname AND k.trigger_name=t.tgname AND k.function_name=p.proname AND pn.nspname='public')
 UNION ALL
 SELECT 'disabled_delete_trigger',c.relname||'.'||t.tgname,t.tgenabled::text
 FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE n.nspname='public' AND NOT t.tgisinternal AND (t.tgtype::integer & 8)<>0 AND t.tgenabled NOT IN ('O','A')
 UNION ALL
 SELECT 'retirement_fence_changed',c.relname||'.'||t.tgname,'Existing fences must preserve exact native INSERT/UPDATE/DELETE authority'
 FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace
 JOIN pg_proc p ON p.oid=t.tgfoid JOIN pg_namespace pn ON pn.oid=p.pronamespace
 WHERE n.nspname='public' AND t.tgname IN ('tenant_retirement_fence','tenant_retirement_org_fence','tenant_retirement_new_org')
 AND (pn.nspname<>'tenant_retirement' OR p.proname<>CASE WHEN t.tgname='tenant_retirement_new_org' THEN 'openbooks_tenant_retirement_new_org' ELSE 'openbooks_tenant_retirement_fence' END
   OR t.tgtype::integer<>CASE WHEN t.tgname='tenant_retirement_new_org' THEN 7 WHEN c.relname='orgs' THEN 27 ELSE 31 END
   OR t.tgenabled NOT IN ('O','A') OR t.tgisinternal OR t.tgnargs<>0 OR t.tgqual IS NOT NULL OR t.tgattr::text<>'' OR t.tgdeferrable OR t.tginitdeferred)
 UNION ALL
 SELECT 'retirement_fence_missing',c.relname::text,'Only the exact production and payroll extension tables may acquire fences in this migration'
 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p')
 AND (EXISTS(SELECT 1 FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attname='org_id' AND NOT a.attisdropped)
   OR c.relname IN ('orgs','app_listings','file_versions','file_blobs','tax_group_members','auth_login_challenges','auth_login_events','auth_login_state','auth_mfa_factors','auth_oidc_identities','auth_password_resets','auth_sessions'))
 AND NOT EXISTS(SELECT 1 FROM production_tables k WHERE k.table_name=c.relname)
 AND NOT EXISTS(SELECT 1 FROM pg_trigger t WHERE t.tgrelid=c.oid AND t.tgname=CASE WHEN c.relname='orgs' THEN 'tenant_retirement_org_fence' ELSE 'tenant_retirement_fence' END)
 UNION ALL
 SELECT 'retirement_new_org_fence_missing','orgs','The native BEFORE INSERT fence must precede company child initialization'
 WHERE NOT EXISTS(SELECT 1 FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace
   WHERE n.nspname='public' AND c.relname='orgs' AND t.tgname='tenant_retirement_new_org')
 UNION ALL
 SELECT 'retirement_authority_changed',k.name,'The published private authority body and execution attributes must remain unchanged'
 FROM authority_functions k WHERE NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang
   WHERE n.nspname='tenant_retirement' AND p.proname=k.name AND encode(public.digest(p.prosrc,'sha256'),'hex')=k.digest
   AND p.prosecdef AND p.prorettype::regtype::text=k.returns AND l.lanname=k.language AND p.provolatile::text=k.volatility
   AND NOT p.proisstrict AND NOT p.proleakproof AND p.proparallel='u'
   AND coalesce((SELECT jsonb_agg(regexp_replace(value,'\s','','g') ORDER BY value) FROM unnest(p.proconfig) value),'[]'::jsonb)=k.config)
 UNION ALL
 SELECT 'retirement_authority_catalog_changed','tenant_retirement','No additional, missing or overloaded authority functions are admitted'
 WHERE (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='tenant_retirement')<>(SELECT count(*) FROM authority_functions)
   OR EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='tenant_retirement' GROUP BY p.proname HAVING count(*)<>1)
 UNION ALL
 SELECT 'retirement_owner_not_isolated','tenant_retirement','Keep the private authority owner separate from the business schema owner'
 WHERE NOT EXISTS(SELECT 1 FROM pg_class ordinary JOIN pg_namespace ons ON ons.oid=ordinary.relnamespace
   CROSS JOIN pg_class authority JOIN pg_namespace ans ON ans.oid=authority.relnamespace
   WHERE ons.nspname='public' AND ordinary.relname='orgs' AND ans.nspname='tenant_retirement' AND authority.relname='runs'
   AND NOT pg_has_role(ordinary.relowner,authority.relowner,'MEMBER'))
)
SELECT '0628.'||problem AS code,'refuse' AS severity,subject,detail,
 'Preserve the schema and tenant data; apply the exact retirement prerequisite and production/payroll source through the native migration runner. Qualify any drift before proceeding.' AS remedy
FROM problems ORDER BY code,subject
;
